flow.typescript:
// D6 · Part 0~6 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d06_flow.ts
//   소리 → 프레임 → (CTC 접기 · Attention 한 글자씩 · Transducer 격자) 까지 세 방식의 핵심을 한 파일에서 맛보기
// 대체 경로: 실제 Wav2Vec2·Whisper 모델은 쓰지 않고, 합성 신호와 손으로 만든 확률표(장난감)로 같은 계산을 한다.
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

// 조합 수 C(n, k): 로그로 계산해 큰 수도 다룬다
function log10Comb(n: number, k: number): number {
  let s = 0;
  for (let i = 1; i <= k; i++) s += Math.log10(n - k + i) - Math.log10(i);
  return s;
}

// 1) 소리 → 프레임: 3초 합성 신호, 20 ms(320샘플)마다 프레임 1개
const y = new Float32Array(3 * SR).map((_, i) => 0.3 * Math.sin((2 * Math.PI * 220 * i) / SR));
const T = Math.floor((y.length - 400) / 320) + 1;
const U = "speech recognition turns sound into text".length;
console.log(`샘플 ${y.length}개 -> 프레임 T=${T}개, 글자 U=${U}개 -> 글자 하나에 평균 ${(T / U).toFixed(1)}프레임`);
check(T > U, "프레임 수 T가 글자 수 U보다 훨씬 많아야 해요(정렬 문제).");

// 2) CTC: 연속 반복 합치기 -> blank 지우기
const collapse = (p: string): string => [...p].filter((c, i, a) => (i === 0 || c !== a[i - 1]) && c !== "-").join("");
console.log("접기: hhe-ll-lloo ->", collapse("hhe-ll-lloo"));
check(collapse("hhe-ll-lloo") === "hello" && collapse("hhel-lo---o") === "helloo", "blank가 사이에 있으면 같은 글자도 두 번 나와요.");

// 3) Attention: 한 글자(query)가 모든 프레임을 훑어 가중치 합 1 을 만든다 (결정적 의사 난수)
let seed = 12345;
const rnd = (): number => {
  seed = (seed * 1103515245 + 12345) % 2147483648;
  return seed / 2147483648 - 0.5;
};
const d = 64;
const q = Array.from({ length: d }, rnd);
const keys = Array.from({ length: 40 }, () => Array.from({ length: d }, rnd));
const scores = keys.map((k) => k.reduce((a, v, i) => a + v * q[i], 0) / Math.sqrt(d));
const m = Math.max(...scores);
const e = scores.map((s) => Math.exp(s - m));
const w = e.map((v) => v / e.reduce((a, b) => a + b, 0));
console.log("가중치 개수:", w.length, "| 합:", w.reduce((a, b) => a + b, 0).toFixed(3));
check(Math.abs(w.reduce((a, b) => a + b, 0) - 1) < 1e-12 && w.length === 40, "attention 가중치의 합은 1이에요.");

// 4) Transducer: 격자 경로 수 C(T+U-1, U) 가 CTC 의 C(T+U, 2U) 보다 훨씬 적다
for (const [t, u] of [[50, 10], [150, 40]]) {
  console.log(`T=${t}, U=${u}: CTC ~ 10^${log10Comb(t + u, 2 * u).toFixed(0)}, Transducer ~ 10^${log10Comb(t + u - 1, u).toFixed(0)}`);
}
check(Math.round(10 ** log10Comb(8, 6)) === 28 && Math.round(10 ** log10Comb(7, 3)) === 35, "공식 C(8,6)=28 (T=5, 'cat').");

align.typescript:
// D6 · Part 1 · 음성 인식은 무엇이 어려운가: 정렬 문제 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d06_align.ts
//   프레임 수 T 와 글자 수 U 가 달라 '어느 프레임이 어느 글자인가' 라벨이 없다는 것 · 가능한 정렬 경로 수를 직접 세어 확인
// 대체 경로: 음성 파일 대신 2.5초 합성 신호(음절처럼 커졌다 작아지는 소리)를 쓴다.
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)
const HOP = 160; // 10 ms 마다 프레임 1개

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const TEXT = "speech recognition turns sound into text";
const y = new Float32Array(Math.floor(2.5 * SR)).map((_, i) => {
  const t = i / SR;
  return (0.3 * Math.sin(2 * Math.PI * 200 * t) * (1 + Math.sin(2 * Math.PI * 3 * t))) / 2;
});
const T = Math.floor(y.length / HOP) + 1;
const U = TEXT.length;
console.log(`문장 "${TEXT}": 글자 U=${U}, 프레임 T=${T} -> 글자 하나에 평균 ${(T / U).toFixed(1)}프레임`);
check(T > U, "프레임이 글자보다 많아야 해요.");

// 작은 크기에서 가능한 정렬을 전부 나열: 프레임 T=5, 정답 'cat', 칸 = blank + 3글자
const fold = (p: string): string => [...p].filter((c, i, a) => (i === 0 || c !== a[i - 1]) && c !== "-").join("");
const vocab = "-cat";
const paths: string[] = [];
const total = vocab.length ** 5;
for (let n = 0; n < total; n++) {
  let p = "";
  let r = n;
  for (let k = 0; k < 5; k++) {
    p += vocab[r % vocab.length];
    r = Math.floor(r / vocab.length);
  }
  if (fold(p) === "cat") paths.push(p);
}
console.log(`T=5 에서 'cat' 으로 접히는 경로 ${paths.length}개, 예: ${paths.slice(0, 5).join(" ")}`);
check(paths.length === 28, "접히는 경로 수는 C(T+U, 2U) = C(8, 6) = 28 이에요.");

// 실제 크기에서는 하나씩 더하는 것이 불가능
let real = 0;
for (let i = 1; i <= 80; i++) real += Math.log10(190 - 80 + i) - Math.log10(i);
console.log(`실제 T=150, U=40 -> 정답으로 접히는 경로 약 10^${real.toFixed(0)}개`);
check(real > 40, "경로 수가 천문학적이라 동적 계획법(α)이 필요해요.");

ctc.typescript:
// D6 · Part 2 · CTC: blank 와 접기 규칙 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d06_ctc.ts
//   CTC 접기 B(): 연속 반복을 하나로 합치고 blank 를 지운다 · blank 가 사이에 있어야 같은 글자가 두 번 나온다
const BLANK = "-";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function ctcCollapse(path: string, blank: string = BLANK): string {
  const merged = [...path].filter((c, i, a) => i === 0 || c !== a[i - 1]); // ① 연속 반복 -> 하나
  return merged.filter((c) => c !== blank).join(""); // ② blank 지우기
}

const tests: Record<string, string> = { "hhe-ll-lloo": "hello", "he-llll-ooo": "helo", "--c-aa--tt-": "cat", "hhel-lo---o": "helloo", "-----": "" };
for (const [p, want] of Object.entries(tests)) {
  const got = ctcCollapse(p);
  console.log(`${p.padStart(12)} -> "${got}" ${got === want ? "맞음" : "틀림"}`);
}
check(Object.entries(tests).every(([p, w]) => ctcCollapse(p) === w), "두 번째 줄에서 지울 것은 blank입니다.");

// 같은 글자를 두 번 쓰려면 사이에 blank 가 꼭 필요하다
check(ctcCollapse("ll") === "l" && ctcCollapse("l-l") === "ll", "'ll' 은 l 하나, 'l-l' 은 l 둘이에요.");

ctcloss.typescript:
// D6 · Part 2 · CTC 격자 · α(forward) 알고리즘 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d06_ctcloss.ts
//   확장 라벨 위에서 α 를 채워 '모든 경로의 합' 을 구하고, 경로를 전부 더한 값과 비교 (PyTorch ctc_loss 비교는 Python 코드에서)
// 대체 경로: 난수 확률표는 결정적 의사 난수로 만든다.
const BLANK = "-";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const collapse = (p: string[]): string => p.filter((c, i, a) => (i === 0 || c !== a[i - 1]) && c !== BLANK).join("");

function ctcForward(probs: number[][], target: string, vocab: string[]): number {
  const lp: string[] = [BLANK];
  for (const ch of target) lp.push(ch, BLANK); // 확장 라벨 l' (길이 2U+1)
  const S = lp.length;
  const T = probs.length;
  const idx = (c: string): number => vocab.indexOf(c);
  const alpha: number[][] = Array.from({ length: T }, () => new Array(S).fill(0));
  alpha[0][0] = probs[0][idx(lp[0])];
  alpha[0][1] = probs[0][idx(lp[1])];
  for (let t = 1; t < T; t++) {
    for (let s = 0; s < S; s++) {
      let a = alpha[t - 1][s]; // 제자리
      if (s >= 1) a += alpha[t - 1][s - 1]; // 한 칸 아래
      if (s >= 2 && lp[s] !== BLANK && lp[s] !== lp[s - 2]) a += alpha[t - 1][s - 2]; // 두 칸 건너뛰기 (같은 글자 연속이면 불가)
      alpha[t][s] = a * probs[t][idx(lp[s])];
    }
  }
  return alpha[T - 1][S - 1] + alpha[T - 1][S - 2];
}

function brute(probs: number[][], target: string, vocab: string[]): number {
  // 정답: 접히는 경로를 전부 더하기
  const T = probs.length;
  const V = vocab.length;
  let tot = 0;
  for (let n = 0; n < V ** T; n++) {
    const p: string[] = [];
    let r = n;
    let prod = 1;
    for (let t = 0; t < T; t++) {
      const k = r % V;
      r = Math.floor(r / V);
      p.push(vocab[k]);
      prod *= probs[t][k];
    }
    if (collapse(p) === target) tot += prod;
  }
  return tot;
}

let seed = 7;
const rnd = (): number => {
  seed = (seed * 1103515245 + 12345) % 2147483648;
  return seed / 2147483648 + 0.05;
};
const vocab = [BLANK, "a", "b", "c", "t"];
const probs = Array.from({ length: 6 }, () => {
  const row = vocab.map(rnd);
  const s = row.reduce((a, b) => a + b, 0);
  return row.map((v) => v / s); // 각 행의 합 = 1
});

let ok = true;
for (const tgt of ["cat", "baa", "ab"]) {
  const pa = ctcForward(probs, tgt, vocab);
  const pb = brute(probs, tgt, vocab);
  console.log(`${tgt}: α ${pa.toExponential(6)} | 전부 더하기 ${pb.toExponential(6)}`);
  ok = ok && Math.abs(pa - pb) < 1e-12 * Math.max(1, pb) + 1e-15;
}
check(ok, "'baa' 처럼 같은 글자가 연달아 나오면 두 칸 건너뛰기를 막아야 해요 (lp[s] != lp[s-2]).");

w2v.typescript:
// D6 · Part 3 · Wav2Vec2 프레임 수 공식 · greedy 디코딩 · 글자 시각 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d06_w2v.ts
//   Wav2Vec2 합성곱 층의 커널·보폭으로 프레임 수 T=floor((L-R)/S)+1 계산, 프레임별 argmax -> 접기 -> 글자 시작 시각(초)
// 대체 경로: wav2vec2-base-960h 모델 대신, 정답 글자가 튀어나오는 시각에 높은 점수를 둔 가짜 logits 로 같은 디코딩을 한다.
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)
const KERNELS = [10, 3, 3, 3, 3, 2, 2]; // Wav2Vec2-base 합성곱 커널
const STRIDES = [5, 2, 2, 2, 2, 2, 2]; // 층별 보폭

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

let R = 1;
let jump = 1;
KERNELS.forEach((k, i) => {
  R += (k - 1) * jump; // 수용 영역이 넓어지는 양
  jump *= STRIDES[i]; // 지금까지의 보폭 곱
});
const S_TOT = jump;
console.log(`수용 영역 R = ${R} 샘플 (${Math.round((R / SR) * 1000)} ms), 전체 보폭 = ${S_TOT} 샘플 (${Math.round((S_TOT / SR) * 1000)} ms)`);

function nFramesLayerwise(len: number): number {
  let L = len;
  KERNELS.forEach((k, i) => {
    L = Math.floor((L - k) / STRIDES[i]) + 1; // 출력 크기 공식 (패딩 0)
  });
  return L;
}

const L = Math.floor(2.0 * SR);
const tFormula = Math.floor((L - R) / S_TOT) + 1;
console.log(`L = ${L} 샘플 -> 공식 ${tFormula} | 층별 ${nFramesLayerwise(L)}`);
check(tFormula === nFramesLayerwise(L) && tFormula === 99 && S_TOT === 320, "나누는 값은 전체 보폭 S_TOT(320)입니다.");

// 가짜 logits: 어휘 = [blank '-', 구분 '|', 알파벳]
const vocab = ["-", "|", ..."abcdefghijklmnopqrstuvwxyz"];
const spikes: Record<number, string> = { 5: "c", 12: "a", 13: "a", 20: "t", 30: "|", 40: "d", 50: "o", 60: "g" };
const ids: number[] = [];
for (let t = 0; t < tFormula; t++) {
  const row = new Array(vocab.length).fill(-4);
  if (spikes[t]) row[vocab.indexOf(spikes[t])] = 6;
  else row[0] = 4; // 대부분 blank
  ids.push(row.indexOf(Math.max(...row))); // 어휘 방향 argmax
}
const path = ids.map((i) => vocab[i]);
const text = path
  .filter((c, i, a) => (i === 0 || c !== a[i - 1]) && c !== "-")
  .join("")
  .replace(/\|/g, " ");
console.log(`디코딩: "${text}" | blank 비율 ${Math.round((ids.filter((i) => i === 0).length / ids.length) * 100)}%`);

const FRAME_SEC = S_TOT / SR; // 프레임 하나 = 0.02초
const charTimes: [string, number][] = [];
path.forEach((p, t) => {
  if (p !== "-" && (t === 0 || p !== path[t - 1])) charTimes.push([p, t * FRAME_SEC]);
});
const words: [string, number, number][] = [];
let cur = "";
let start = 0;
for (const [ch, ts] of [...charTimes, ["|", tFormula * FRAME_SEC] as [string, number]]) {
  if (ch === "|") {
    if (cur) {
      words.push([cur, start, ts]);
      cur = "";
    }
  } else {
    if (!cur) start = ts;
    cur += ch;
  }
}
for (const [w, s, e] of words) console.log(`${s.toFixed(2)} ~ ${e.toFixed(2)} s  ${w}`);
check(text === "cat dog" && Math.abs(FRAME_SEC - 0.02) < 1e-12 && Math.abs(words[0][1] - 0.1) < 1e-9, "한 프레임 = 320/16000 = 0.02초, 단어 시작은 첫 글자 프레임 x 0.02초입니다.");

attn.typescript:
// D6 · Part 4 · Attention Encoder-Decoder: scaled dot-product attention · 한 글자씩 생성 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d06_attn.ts
//   attention 을 식 그대로 구현, 점수 분산 = d 이고 √d 로 나누면 1, 한 글자씩 읽어 가는 장난감 디코더 (PyTorch 비교는 Python 코드에서)
// 대체 경로: Whisper-tiny 모델 대신, 프레임마다 글자 특징이 들어 있는 장난감 인코더 출력과 직접 만든 query 로 cross-attention 을 흉내 낸다.
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

// 결정적 정규분포 난수 (Box-Muller)
let seed = 2024;
const uni = (): number => {
  // mulberry32: 작지만 고르게 퍼지는 의사 난수 (0 초과 1 미만)
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return (((t ^ (t >>> 14)) >>> 0) + 0.5) / 4294967296;
};
const randn = (): number => Math.sqrt(-2 * Math.log(uni())) * Math.cos(2 * Math.PI * uni());
const vec = (n: number, s: number = 1): number[] => Array.from({ length: n }, () => s * randn());
const dot = (a: number[], b: number[]): number => a.reduce((s, v, i) => s + v * b[i], 0);
const softmax = (z: number[]): number[] => {
  const m = Math.max(...z);
  const e = z.map((v) => Math.exp(v - m));
  const s = e.reduce((a, b) => a + b, 0);
  return e.map((v) => v / s);
};
const variance = (x: number[]): number => {
  const m = x.reduce((a, b) => a + b, 0) / x.length;
  return x.reduce((a, b) => a + (b - m) ** 2, 0) / (x.length - 1);
};

// q·k 의 분산은 d -> √d 로 나누면 1 (softmax 가 한쪽으로 쏠리는 것을 막는다)
let ok = true;
for (const d of [16, 64, 256, 1024]) {
  const raw = Array.from({ length: 4000 }, () => dot(vec(d), vec(d)));
  const v1 = variance(raw);
  const v2 = variance(raw.map((r) => r / Math.sqrt(d)));
  console.log(`d=${String(d).padStart(5)} | 점수 분산 ${v1.toFixed(1)} (이론 ${d}) | √d 로 나눈 뒤 ${v2.toFixed(2)}`);
  ok = ok && Math.abs(v1 / d - 1) < 0.15 && Math.abs(v2 - 1) < 0.15;
}
check(ok, "점수 분산은 d 에 가깝고, √d 로 나누면 1 에 가까워야 해요.");

// 한 글자씩 생성하는 장난감 디코더: 인코더 프레임 40개에 글자 4개가 구간별로 들어 있고, query 가 해당 구간을 본다
const letters = "cat!"; // '!' = 끝(EOS)
const codes: Record<string, number[]> = {};
for (const c of letters) codes[c] = vec(32);
const enc: number[][] = [];
for (const c of letters) for (let i = 0; i < 10; i++) enc.push(codes[c].map((v) => v + 0.1 * randn()));
let gen = "";
const peak: number[] = [];
for (let i = 0; i < letters.length; i++) {
  const qv = codes[letters[i]].map((v) => v * 3); // 학습된 디코더가 '지금 들을 곳' 을 만들어 낸다고 가정
  const wt = softmax(enc.map((f) => dot(f, qv) / Math.sqrt(32)));
  const ctx = enc[0].map((_, j) => wt.reduce((s, w, t) => s + w * enc[t][j], 0)); // 가중합 = 문맥 벡터
  const pred = [...letters].reduce((best, c) => (dot(ctx, codes[c]) > dot(ctx, codes[best]) ? c : best), letters[0]);
  gen += pred;
  peak.push(wt.indexOf(Math.max(...wt)));
  if (pred === "!") break;
}
console.log("생성:", gen, "| 스텝별 가장 많이 본 프레임:", peak.join(", "));
check(gen === "cat!" && peak.every((p, i) => i === 0 || p > peak[i - 1]) && peak[0] < 10 && peak[1] >= 10 && peak[1] < 20, "글자를 쓸수록 보는 프레임이 오른쪽으로 이동(대각선)해야 해요.");

rnnt.typescript:
// D6 · Part 5 · Transducer (RNN-T): T x (U+1) 격자와 α 점화식 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d06_rnnt.ts
//   log 공간 α 점화식으로 모든 경로의 합을 구하고, 경로를 전부 나열해 더한 값과 비교 · 경로 수 C(T+U-1, U)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const logaddexp = (a: number, b: number): number => {
  if (a === -Infinity) return b;
  if (b === -Infinity) return a;
  const m = Math.max(a, b);
  return m + Math.log(Math.exp(a - m) + Math.exp(b - m));
};

// logp[t][u][v]: 격자 각 점에서의 log 확률, y: 정답 글자 번호 (길이 U)
function rnntForward(logp: number[][][], y: number[], blank: number = 0): number {
  const T = logp.length;
  const U1 = logp[0].length;
  const alpha = Array.from({ length: T }, () => new Array(U1).fill(-Infinity));
  alpha[0][0] = 0;
  for (let t = 0; t < T; t++) {
    for (let u = 0; u < U1; u++) {
      if (t === 0 && u === 0) continue;
      let a = -Infinity;
      if (t > 0) a = logaddexp(a, alpha[t - 1][u] + logp[t - 1][u][blank]); // 왼쪽에서 ∅를 내고 옴
      if (u > 0) a = logaddexp(a, alpha[t][u - 1] + logp[t][u - 1][y[u - 1]]); // 아래에서 u번째 글자를 내고 옴
      alpha[t][u] = a;
    }
  }
  return alpha[T - 1][U1 - 1] + logp[T - 1][U1 - 1][blank];
}

// 정답: 글자를 내는 걸음 위치(조합)를 전부 나열해 더하기
function rnntBrute(logp: number[][][], y: number[], blank: number = 0): [number, number] {
  const T = logp.length;
  const U = logp[0].length - 1;
  const steps = T + U - 1; // 마지막 걸음(∅)을 뺀 걸음 수
  let tot = -Infinity;
  let n = 0;
  for (let mask = 0; mask < 1 << steps; mask++) {
    let bits = 0;
    for (let k = 0; k < steps; k++) if (mask & (1 << k)) bits++;
    if (bits !== U) continue;
    let t = 0;
    let u = 0;
    let lp = 0;
    for (let k = 0; k < steps; k++) {
      if (mask & (1 << k)) {
        lp += logp[t][u][y[u]];
        u++;
      } else {
        lp += logp[t][u][blank];
        t++;
      }
    }
    tot = logaddexp(tot, lp + logp[t][u][blank]);
    n++;
  }
  return [tot, n];
}

let seed = 1;
const randn = (): number => {
  const uni = (): number => {
    seed = (seed * 1103515245 + 12345) % 2147483648;
    return (seed + 1) / 2147483649;
  };
  return Math.sqrt(-2 * Math.log(uni())) * Math.cos(2 * Math.PI * uni());
};
const T5 = 5;
const y5 = [2, 1, 3]; // 정답 3글자, 어휘 = ∅ + 3글자
const V5 = 4;
const logp5 = Array.from({ length: T5 }, () =>
  Array.from({ length: y5.length + 1 }, () => {
    const z = Array.from({ length: V5 }, randn);
    const lse = Math.log(z.reduce((a, v) => a + Math.exp(v), 0));
    return z.map((v) => v - lse); // log_softmax
  }),
);

const ll = rnntForward(logp5, y5);
const [bl, nPaths] = rnntBrute(logp5, y5);
console.log(`log P: α 점화식 ${ll.toFixed(6)} | 경로 ${nPaths}개 전부 더하기 ${bl.toFixed(6)} (공식 C(T+U-1, U) = 35)`);
check(Math.abs(ll - bl) < 1e-9 && nPaths === 35, "점 (t, u-1)에서 내는 글자는 u번째 글자, 0부터 세면 y[u - 1]입니다.");

const log10Comb = (n: number, k: number): number => {
  let s = 0;
  for (let i = 1; i <= k; i++) s += Math.log10(n - k + i) - Math.log10(i);
  return s;
};
for (const [t, u] of [[50, 10], [150, 40]]) {
  console.log(`T=${t}, U=${u}: CTC ~ 10^${log10Comb(t + u, 2 * u).toFixed(0)}, Transducer ~ 10^${log10Comb(t + u - 1, u).toFixed(0)}  -> 둘 다 α(동적 계획법)로 O(T·U)`);
}
check(log10Comb(189, 40) < log10Comb(190, 80), "Transducer 경로 수가 CTC 보다 적어요.");

compare.typescript:
// D6 · Part 5 · 세 방식 비교: CTC · Attention Enc-Dec · Transducer — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d06_compare.ts
//   첫 글자를 내보내기까지 기다려야 하는 프레임 수(스트리밍 가능 여부)와 경로 수를 숫자로 비교
// 대체 경로: 실제 모델 대신 '프레임 t 까지 들은 소리만 쓸 수 있는가' 규칙만으로 첫 글자가 나오는 시각을 계산한다.
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const log10Comb = (n: number, k: number): number => {
  let s = 0;
  for (let i = 1; i <= k; i++) s += Math.log10(n - k + i) - Math.log10(i);
  return s;
};

const T = 100; // 2초 음성 = 20 ms 프레임 100개
const firstCharFrame = 30; // 소리 속에서 첫 글자가 실제로 들리는 프레임(장난감)

// CTC · Transducer: 프레임을 하나씩 받으며 그때그때 글자를 낼 수 있다 -> 첫 글자 시각 = 들린 직후
// AED(Attention): 인코더가 소리 전체를 본 뒤에야 디코더가 시작한다 -> 첫 글자 시각 = 마지막 프레임
const wait: Record<string, number> = { CTC: firstCharFrame, Transducer: firstCharFrame, "Attention Enc-Dec": T };
const rows: [string, string, string, number | null][] = [
  ["CTC", "프레임끼리 독립", "가능(프레임마다 출력)", log10Comb(190, 80)],
  ["Attention Enc-Dec", "앞 글자에 조건부", "어려움(전체 필요)", null],
  ["Transducer", "앞 글자 + 프레임", "가능(스트리밍)", log10Comb(189, 40)],
];
console.log("방식 | 가정 | 스트리밍 | 첫 글자까지 기다린 프레임 | 경로 수(T=150,U=40)");
for (const [name, assume, stream, lg] of rows) {
  const paths = lg === null ? "해당 없음(한 글자씩 생성)" : `10^${lg.toFixed(0)}`;
  console.log(`${name} | ${assume} | ${stream} | ${wait[name]} | ${paths}`);
}

check(wait["Attention Enc-Dec"] > wait["CTC"] && wait["CTC"] === wait["Transducer"] && (rows[2][3] as number) < (rows[0][3] as number),
  "스트리밍은 CTC·Transducer, AED는 소리 전체를 기다려요. 경로 수는 Transducer 가 더 적어요.");

ssl.typescript:
// D6 · Part 6 · 자기지도 학습: 가려진 비율 · InfoNCE 대조 손실 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d06_ssl.ts
//   wav2vec2 식 마스킹: 시작점 확률 p, 길이 M 이면 가려지는 비율 1-(1-p)^M · InfoNCE 를 식 그대로 구해 '-log softmax' 와 비교
// 대체 경로: 사전학습 모델 대신 난수 벡터로 같은 손실 식을 계산한다.
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

let seed = 99;
const uni = (): number => {
  // mulberry32: 작지만 고르게 퍼지는 의사 난수 (0 초과 1 미만)
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return (((t ^ (t >>> 14)) >>> 0) + 0.5) / 4294967296;
};
const randn = (): number => Math.sqrt(-2 * Math.log(uni())) * Math.cos(2 * Math.PI * uni());

// 가려지는 비율: 공식과 시뮬레이션
let ok = true;
for (const [p, M] of [[0.065, 10], [0.065, 5], [0.03, 10]]) {
  const L = 500;
  const trials = 400;
  let masked = 0;
  let counted = 0;
  for (let n = 0; n < trials; n++) {
    const m = new Array(L).fill(false);
    for (let i = 0; i < L; i++) {
      if (uni() < p) for (let k = 0; k < M && i + k < L; k++) m[i + k] = true; // 시작점부터 M칸 가리기
    }
    for (let i = M; i < L; i++) {
      counted++;
      if (m[i]) masked++;
    }
  }
  const sim = masked / counted;
  const formula = 1 - (1 - p) ** M;
  console.log(`p=${p}, M=${String(M).padStart(2)} | 공식 ${formula.toFixed(3)} | 시뮬레이션 ${sim.toFixed(3)}`);
  ok = ok && Math.abs(sim - formula) < 0.03;
}
check(ok, "가려지는 비율은 1 - (1-p)^M 에 가까워야 해요.");

// InfoNCE: 후보 101개 중 0번 칸이 진짜
const T = 8;
const K = 100;
const D = 64;
const kappa = 0.1;
const cosine = (a: number[], b: number[]): number => {
  const dot = a.reduce((s, v, i) => s + v * b[i], 0);
  return dot / (Math.hypot(...a) * Math.hypot(...b));
};
let lossManual = 0;
let hit = 0;
for (let t = 0; t < T; t++) {
  const c = Array.from({ length: D }, randn);
  const pos = c.map((v) => v + 3 * randn()); // 진짜 q_t: c_t 와 조금 닮음 (잡음이 큼)
  const cands = [pos, ...Array.from({ length: K }, () => Array.from({ length: D }, randn))]; // 0번 칸 = 진짜
  const sims = cands.map((q) => cosine(c, q) / kappa);
  const m = Math.max(...sims);
  const lse = m + Math.log(sims.reduce((s, v) => s + Math.exp(v - m), 0));
  lossManual += -(sims[0] - lse) / T; // -log softmax 의 0번 칸 평균
  if (sims.indexOf(m) === 0) hit++;
}
console.log(`InfoNCE ${lossManual.toFixed(4)} | 진짜를 1등으로 고른 비율 ${Math.round((hit / T) * 100)}%`);
console.log(`참고: 무작위로 고르면 손실 log(101) = ${Math.log(101).toFixed(3)}`);
check(lossManual < Math.log(101) && lossManual >= 0, "진짜는 0번 칸이고, 손실은 무작위(log 101)보다 작아야 해요.");
